"""Bind validation evidence to the exact clinical and documentation artifacts."""

import hashlib
from pathlib import Path


def artifact_snapshot(root, study):
    """Inventory source, reference and generated bytes used by publication.

    Discover the complete set again on verification so additions and deletions
    cannot silently reuse an earlier successful record. CORE reports and caches
    are separate evidence and are not inputs to this publication path.
    """
    root = Path(root).resolve()
    base = root / study
    files = set()
    for relative in (
        ".github/yamaa-studies.json",
        ".github/dashboard.json",
        ".github/scripts/validate_yamaa.py",
        ".github/scripts/study_artifacts.py",
        ".github/scripts/study_evidence.py",
        ".github/scripts/compare_adam.py",
    ):
        path = root / relative
        if path.is_file():
            files.add(path)
    for directory in (base / "spec", base / "data", base / "program/adam/python"):
        for path in directory.rglob("*"):
            if not path.is_file() or any(
                p.startswith(".") or p == "__pycache__"
                for p in path.relative_to(directory).parts
            ):
                continue
            if path.name.startswith("core-report-") or path.name in {
                "dataset_comment.md",
                "core-execution.json",
            }:
                continue
            if directory.name == "data" and path.suffix not in {
                ".parquet",
                ".csv",
                ".xpt",
            }:
                continue
            files.add(path)
    hashes = {}
    for path in sorted(files):
        # Resolve to keep source aliases/symlinks inside the repository boundary.
        path.resolve().relative_to(root)
        digest = hashlib.sha256()
        with path.open("rb") as source:
            for block in iter(lambda: source.read(1024 * 1024), b""):
                digest.update(block)
        hashes[path.relative_to(root).as_posix()] = digest.hexdigest()
    return {"algorithm": "sha256", "files": hashes}


def verify_artifacts(root, study, report):
    expected = report.get("artifacts")
    if not expected or expected.get("algorithm") != "sha256":
        raise ValueError(
            f"{study}: validation record has no supported artifact snapshot; rerun validation"
        )
    actual = artifact_snapshot(root, study)
    if actual != expected:
        old, new = expected.get("files", {}), actual["files"]
        changed = sorted(
            name for name in set(old) | set(new) if old.get(name) != new.get(name)
        )
        raise ValueError(
            f'{study}: artifacts changed after validation: {", ".join(changed[:8])}'
        )


def verify_report_artifacts(root, entries, reports):
    for study in entries:
        if reports[study]["status"] != "pending":
            verify_artifacts(root, study, reports[study])
